INSERT INTO `article_block` (`id_block`, `id_article`, `type_block`, `article_type`, `contenu`, `contenu_json`, `id_media`, `ordre`, `metadata`, `visible`, `date_creation`, `date_modification`) VALUES
(1, 2, 'heading', 'article_scientifique', '1. Introduction', NULL, NULL, 0, '{\"level\": 2}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(2, 2, 'text', 'article_scientifique', 'Présentez le contexte de votre recherche, la problématique étudiée et les objectifs de l\'étude. Terminez par l\'annonce du plan de l\'article.', NULL, NULL, 1, '{\"alignment\": \"justify\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(3, 2, 'heading', 'article_scientifique', '2. Revue de littérature', NULL, NULL, 2, '{\"level\": 2}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(4, 2, 'text', 'article_scientifique', 'Synthétisez les travaux antérieurs pertinents. Identifiez les lacunes dans la littérature existante que votre recherche vise à combler.', NULL, NULL, 3, '{\"alignment\": \"justify\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(5, 2, 'heading', 'article_scientifique', '3. Méthodologie', NULL, NULL, 4, '{\"level\": 2}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(6, 2, 'text', 'article_scientifique', 'Décrivez votre approche méthodologique : type de recherche, échantillon, instruments de collecte de données, procédure d\'analyse.', NULL, NULL, 5, '{\"alignment\": \"justify\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(7, 2, 'heading', 'article_scientifique', '4. Résultats', NULL, NULL, 6, '{\"level\": 2}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(8, 2, 'text', 'article_scientifique', 'Présentez vos résultats de manière objective. Utilisez des tableaux, figures et graphiques pour illustrer vos données.', NULL, NULL, 7, '{\"alignment\": \"justify\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(9, 2, 'image', 'article_scientifique', '', NULL, 10, 8, '{\"layout\": \"full-width\", \"caption\": \"Figure 1 : Insérez ici un graphique ou une illustration de vos résultats\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(10, 2, 'heading', 'article_scientifique', '5. Discussion', NULL, NULL, 9, '{\"level\": 2}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(11, 2, 'text', 'article_scientifique', 'Interprétez vos résultats en les comparant à la littérature existante. Discutez les implications, les limites de l\'étude et les perspectives futures.', NULL, NULL, 10, '{\"alignment\": \"justify\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(12, 2, 'heading', 'article_scientifique', '6. Conclusion', NULL, NULL, 11, '{\"level\": 2}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(13, 2, 'text', 'article_scientifique', 'Résumez les principaux apports de votre recherche et proposez des pistes pour de futurs travaux.', NULL, NULL, 12, '{\"alignment\": \"justify\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(14, 2, 'heading', 'article_scientifique', 'Références', NULL, NULL, 13, '{\"level\": 2}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21'),
(15, 2, 'text', 'article_scientifique', '[1] Nom, P. (Année). Titre de l\'article. Nom du journal, Volume(Numéro), pages. DOI\n[2] Nom, P. (Année). Titre du livre. Éditeur.', NULL, NULL, 14, '{\"alignment\": \"left\"}', 1, '2026-02-23 22:47:21', '2026-02-23 22:47:21');
